// Claude's review tests for A22 (duplicate), A23 (one-scenario files) and A24 (Log as HAR). agy: do not edit this file.
import { describe, expect, it } from 'vitest';
import { exportScenario, parseScenarioFile } from './exportFile';
import { logToHar } from './harExport';
import { importHar } from './harImport';
import { scenarioFromLogs } from './record';
import { addScenario, duplicateMock, duplicateScenario, duplicateSocket } from './scenarioOps';
import type { LogEntry, Mock, Project, Scenario, SocketMock } from './types';

const counter = () => {
  let n = 0;
  return () => `n${++n}`;
};

function mock(id: string, name?: string): Mock {
  return {
    id, ...(name ? { name } : {}), enabled: true, method: 'GET', urlPattern: `/api/${id}`,
    response: { status: 200, headers: {}, body: id, bodyEncoding: 'text', delayMs: 0 }, source: 'manual', createdAt: 1,
  };
}
const sock = (id: string, name?: string): SocketMock => ({
  id, ...(name ? { name } : {}), enabled: true, kind: 'plain', urlPattern: `/ws/${id}`,
  onConnect: [{ id: `${id}-p`, afterMs: 0, target: '', data: 'hi' }], replies: [], createdAt: 1,
});

function project(): Project {
  return {
    id: 'p', name: 'site', origins: ['http://a.test'], activeScenarioId: 'default',
    scenarios: [
      { id: 'default', name: 'Default', mocks: [mock('a', 'Alpha'), mock('b')], sockets: [sock('s', 'Feed')] },
      { id: 'x', name: 'Beta', mocks: [mock('c')] },
      { id: 'y', name: 'Beta (2)', mocks: [] },
    ],
  };
}

describe('A22 duplicateMock / duplicateSocket', () => {
  it('puts a copy right after the original, named (copy), with a new id', () => {
    const r = duplicateMock(project(), 'default', 'a', counter());
    const ms = r.project.scenarios[0]!.mocks;
    expect(ms.map((m) => m.id)).toEqual(['a', 'n1', 'b']);
    expect(ms[1]).toEqual({ ...mock('a', 'Alpha (copy)'), id: 'n1' });
    expect(r.newId).toBe('n1');
  });
  it('an unnamed mock is named from its pattern', () => {
    const r = duplicateMock(project(), 'default', 'b', counter());
    expect(r.project.scenarios[0]!.mocks[2]!.name).toBe('/api/b (copy)');
  });
  it('a socket copy gets new ids for itself and its messages', () => {
    const r = duplicateSocket(project(), 'default', 's', counter());
    const ss = r.project.scenarios[0]!.sockets!;
    expect(ss.map((s) => s.name)).toEqual(['Feed', 'Feed (copy)']);
    expect(ss[1]!.id).not.toBe('s');
    expect(ss[1]!.onConnect[0]!.id).not.toBe('s-p');
    expect(ss[1]!.onConnect[0]!.data).toBe('hi');
  });
  it('unknown ids change nothing; inputs are not changed', () => {
    const p = project();
    const before = JSON.stringify(p);
    expect(duplicateMock(p, 'default', 'zz', counter()).project).toEqual(p);
    expect(JSON.stringify(p)).toBe(before);
  });
});

describe('A22 duplicateScenario', () => {
  it('puts a copy right after it, with a free name and new ids everywhere', () => {
    const r = duplicateScenario(project(), 'x', counter());
    const sc = r.project.scenarios;
    expect(sc.map((s) => s.name)).toEqual(['Default', 'Beta', 'Beta (3)', 'Beta (2)']);
    expect(sc[2]!.id).toBe(r.newId);
    expect(sc[2]!.mocks[0]!.id).not.toBe('c');
    expect(sc[2]!.mocks[0]!.urlPattern).toBe('/api/c');
    expect(r.project.activeScenarioId).toBe('default');
  });
  it('Default can be copied; the copy is an ordinary scenario', () => {
    const r = duplicateScenario(project(), 'default', counter());
    expect(r.project.scenarios[0]!.id).toBe('default');
    expect(r.project.scenarios[1]!.name).toBe('Default (2)');
    expect(r.project.scenarios[1]!.sockets!.map((s) => s.urlPattern)).toEqual(['/ws/s']);
  });
});

describe('A23 one-scenario files', () => {
  const beta: Scenario = { id: 'x', name: 'Beta', mocks: [mock('c')], sockets: [sock('t')] };
  it('round-trips a scenario', () => {
    const r = parseScenarioFile(exportScenario(beta));
    expect(r.ok && r.scenario).toEqual(beta);
    expect(JSON.parse(exportScenario(beta))).toMatchObject({ wemock: 'scenario', schemaVersion: 1 });
  });
  it('rejects a project file, a bad mock and junk', () => {
    expect(parseScenarioFile('{"wemock":"project","schemaVersion":1}').ok).toBe(false);
    const bad = JSON.parse(exportScenario(beta));
    bad.scenario.mocks[0].response.status = 'x';
    expect(parseScenarioFile(JSON.stringify(bad)).ok).toBe(false);
    expect(parseScenarioFile('nope').ok).toBe(false);
  });
  it('addScenario appends with a free name and new ids, never into Default', () => {
    const p1 = addScenario(project(), beta, counter());
    expect(p1.scenarios.map((s) => s.name)).toEqual(['Default', 'Beta', 'Beta (2)', 'Beta (3)']);
    const added = p1.scenarios[3]!;
    expect(added.id).not.toBe('x');
    expect(added.mocks[0]!.id).not.toBe('c');
    expect(added.sockets![0]!.id).not.toBe('t');
    const p2 = addScenario(project(), { ...beta, name: 'Default' }, counter());
    expect(p2.scenarios[0]!.mocks.map((m) => m.id)).toEqual(['a', 'b']);
    expect(p2.scenarios.at(-1)!.name).toBe('Default (2)');
    expect(p2.activeScenarioId).toBe('default');
  });
});

describe('A24 logToHar', () => {
  const e = (id: string, extra: Partial<LogEntry>): LogEntry => ({
    id, method: 'GET', url: 'http://a.test/api/x', status: 200, responseHeaders: { 'content-type': 'application/json' },
    responseBody: '{"a":1}', responseEncoding: 'text', truncated: false, durationMs: 12, badge: 'real', startedAt: 1_700_000_000_000, ...extra,
  });
  const entries: LogEntry[] = [
    e('1', {}),
    e('2', { method: 'POST', url: 'http://a.test/api/y', requestBody: '{"q":1}', status: 201, badge: 'MOCK' }),
    e('3', { url: 'http://a.test/img', responseHeaders: { 'content-type': 'image/png' }, responseBody: 'AAEC', responseEncoding: 'base64' }),
    e('4', { method: 'WS', url: 'ws://a.test/ws', status: 101 }),
    e('5', { method: 'WS ↓', url: 'ws://a.test/ws', status: 0, responseBody: 'tick' }),
  ];
  it('writes HAR 1.2 for HTTP rows and counts the socket rows it leaves out', () => {
    const { har, skippedSockets } = logToHar(entries);
    expect(skippedSockets).toBe(2);
    const h = har as { log: { version: string; creator: { name: string }; entries: Array<Record<string, any>> } }; // eslint-disable-line @typescript-eslint/no-explicit-any
    expect(h.log.version).toBe('1.2');
    expect(h.log.creator.name).toBe('wemock');
    expect(h.log.entries).toHaveLength(3);
    const [a, b, c] = h.log.entries;
    expect(a!.startedDateTime).toBe(new Date(1_700_000_000_000).toISOString());
    expect(a!.time).toBe(12);
    expect(a!.request).toMatchObject({ method: 'GET', url: 'http://a.test/api/x' });
    expect(a!.response).toMatchObject({ status: 200, statusText: 'OK', content: { mimeType: 'application/json', text: '{"a":1}' } });
    expect(a!.response.headers).toEqual([{ name: 'content-type', value: 'application/json' }]);
    expect(a!._resourceType).toBe('fetch');
    expect(b!.request.postData).toEqual({ mimeType: 'application/json', text: '{"q":1}' });
    expect(b!._wemockBadge).toBe('MOCK');
    expect(c!.response.content).toMatchObject({ mimeType: 'image/png', text: 'AAEC', encoding: 'base64' });
  });
  it('a saved HAR imports back to the same mocks', () => {
    const real = entries.filter((x) => x.badge === 'real');
    const back = importHar(logToHar(real).har, 'x.har', 'http://a.test', counter(), 5);
    if (!back.ok) throw new Error(back.error);
    const direct = scenarioFromLogs(real.filter((x) => !x.method.startsWith('WS')), 'HAR x.har', counter(), 5, 'http://a.test');
    const strip = (s: Scenario) => s.mocks.map(({ id: _id, ...m }) => m);
    expect(strip(back.result.project.scenarios[1]!)).toEqual(strip(direct));
  });
});
